SELECT * FROM tb_contract
WHERE owner_id = #{ownerId}

    AND status = #{status}

ORDER BY created_at DESC

SELECT * FROM tb_contract
WHERE renter_id = #{renterId}
ORDER BY created_at DESC

SELECT * FROM tb_contract
WHERE ship_id = #{shipId}
ORDER BY created_at DESC

SELECT COUNT(*) FROM tb_contract
WHERE owner_id = #{ownerId}

    AND status = #{status}

SELECT COUNT(*) FROM tb_contract
WHERE renter_id = #{renterId}

    AND status = #{status}

SELECT COALESCE(SUM(total_amount), 0) FROM tb_contract
WHERE owner_id = #{ownerId}
  AND status IN ('APPROVED', 'IN_PROGRESS', 'COMPLETED')

SELECT COALESCE(SUM(total_amount), 0) FROM tb_contract
WHERE renter_id = #{renterId}
  AND status IN ('APPROVED', 'IN_PROGRESS', 'COMPLETED')
